import React, { useState } from "react";
import { useEffect } from "react";
import { useLocation } from "react-router-dom";
import GetInTouch from "src/views/pages/Services/GetInTouch";
import GetInTouchView from "src/views/pages/Services/GetInTouchView";
import Introduction from "src/views/pages/Services/Introduction";
import ManageServices from "src/views/pages/Services/ManageServices";

const ServicesPage = () => {
  useEffect(() => {
    window.scrollTo(0, 0); // Scroll to the top when the component mounts
  }, []);
  const [serviceType, setServiceType] = useState("engine");

  const updateServiceType = (serviceType) => {
    if (serviceType) {
      setServiceType(serviceType);
    }
  };
  const title =
    serviceType === "engine"
      ? "Take control of your IT"
      : "Your life's work,powered by our life's work";
  const description =
    serviceType === "engine"
      ? "Monitor, manage, and secure your IT infrastructure with enterprise-grade solutions built from the ground up"
      : "A unique and powerful software suite to transform the way you work. Designed for businesses of all sizes, built by a company that values your privacy.";
  return (
    <>
      <Introduction title={title} description={description} />
      <ManageServices updateServiceType={updateServiceType} />
      {/* <GetInTouch /> */}
      <GetInTouchView />
    </>
  );
};

export default ServicesPage;
